INSERT INTO "public"."wiki_pages" VALUES ('394dec1a-a18d-45f1-92ff-ae8bd3d83963', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'entity/legal-subjects', '法律主体类', 'entity', 'published', '# 法律主体类

法律主体类，又称法律关系主体类，是指法律关系中权利义务的承担者类别。

## 涵盖范围
法律主体类主要涵盖以下几类主体：
- 自然人
- 法人
- 非法人组织

从具体法律领域的实践来看，法律主体通常表现为单位与个人两大基本类型，在不同部门法中呈现出多样化的具体形态：
- 在社会保险法律关系中，主体包括用人单位、职工（个人）、社会保险经办机构、社会保险行政部门、工会组织等。
- 在商业保险法律关系中，主体包括投保人、保险人、被保险人、受益人、保险代理人、保险经纪人等。

## 主要特征
法律主体是法律关系的构成要素之一，依法享有权利并承担相应义务，是法律规范调整社会关系的直接承载者。不同类型的法律主体在权利能力、行为能力及责任承担方式上存在差异，由相关法律予以具体规定。

法律主体具有以下基本特征：
1. **法定性**：法律主体的资格、范围及权利义务内容由法律明确规定。
2. **权利义务统一性**：法律主体既是权利的享有者，也是义务的承担者。
3. **类型差异性**：不同类型的法律主体（如自然人与法人）在权利能力、行为能力和责任承担方式上存在显著区别。
4. **具体性**：法律主体是具体法律关系的实际参加者，其权利义务的内容取决于具体法律关系的性质。', '法律主体类是法律关系中权利义务的承担者类别，涵盖自然人、法人、非法人组织等类型，具有法定性与权利义务统一性。', '', 'd42b9f51-7c48-426b-a6b0-8b898d6ba0bc', '["法律相关", "主体类别"]', 'entity/法律相关/主体类别/法律主体类', 2, 0, '["09f98df9-1d2e-4e78-942e-827aa98c8340", "48257422-e389-4722-b0c7-f468b15d3b70", "f10d24ba-f395-4ea2-a362-82b161c78439", "545e625f-0915-4665-b5a1-d07622997253", "a80a58b2-6424-4d94-a41a-a97be2e9999e"]', '["98e174b2-0808-485d-9a91-0a4652b1d5e2", "c08040d9-0fca-41a6-ae75-c18031d98405", "49ab33ac-b9d6-4fee-96e9-2e06e664aa2e", "6a519d6c-2d30-4827-9952-69ba0f039318", "da7ec3f0-3071-4cad-a761-ff740cd73287", "ca78f84e-1670-427c-99ef-936e764f2613", "ac0a10f0-0eb6-4119-ad75-ebcde90fe4e3", "9b6fc388-ac48-47df-a22d-e5acb19956de", "d64cd4f7-5dd9-439e-b0cf-9dfbcdc4445e", "ea7a9d06-e899-4647-a63d-89d7e532abbf", "1dee7c2b-4da7-4dea-8c46-9b8fb796281d", "065aff8c-31e8-4de2-88f1-90a733cba53c", "78a5f990-7443-459e-9e76-f2fa88c88d8d", "8f530b67-c6f3-4ed6-acdc-bbd75a793b25", "932408f2-81e4-490a-a000-ae00e9cc9e38", "17fb92b5-7887-404e-ac6e-78a3f7194888", "20ef308f-66ff-4b8f-a025-435cd3f28e90", "91c4b058-ea0c-424d-8142-9ed49c8beb08", "15cd894e-0a80-47f2-8fcb-083b4c8d2e49", "bd312471-4277-4bc3-a706-219ae10ea96d", "079aead6-03ba-4bf5-93fd-123b09420bce", "d091acd8-2b7f-4191-a3a8-c6d4b80e5262", "3982707d-7d60-4421-b11a-6f1e870bc56b", "ae127986-091e-455c-bcc8-609cc23433a6", "9d5a586d-248d-4bde-820c-04fe63e6b0ea", "5fde47e7-bb0b-4561-a4a8-57902fad9930", "62638a93-13ab-4db3-8c26-ffd2ba4e5502", "7adff4c4-e2b1-4729-89fb-7968eacaf74b", "fabb7dba-a327-4cd5-82f3-d95042f81d55", "4715d119-1455-4919-bbf8-dcfd213ff2d0", "af5ce600-e5b4-4ae6-90ed-f2d37e8fae85", "13c93e2c-0aa9-4bfd-8cbc-53358832e3ec", "5a1f050d-daed-4b5f-87e2-2c3652849c2b", "69aa4164-2585-42e9-8dbe-6dce46a7941f", "f2bba6ac-a134-47c3-83cb-e79238e726d1", "77a2b7ee-8a55-414c-b21e-779481adde4c", "4c593259-aeff-4909-b19e-73879f24434d", "64ce6281-ebc7-4d9f-8f50-be080594ffa7", "c384bbbf-1ed3-45e6-b27b-442651cec6fe", "68dddbe3-0495-4de3-8d3e-54d9749404b8", "d4dd66df-c6f5-4791-8a3f-357c50e49911", "134e9a01-4576-48c9-947b-5d570ab6bb2a", "78307b54-53b7-479b-85e7-571778463168", "1ea7c4ec-0268-4f4a-ad86-ced19199d79b", "8fece6d2-202f-4666-a50e-369e99878a88", "c5f281d6-b9b1-4307-9f50-637ebc465689", "6310e20d-0f0e-49bb-aada-95e7c2983f44", "b696cb43-c2bd-4507-9d7d-de0d88e71a67", "aa6bc7c8-790e-4206-afe6-34dfcf02a15d", "0a85dcd2-f7a2-4845-ac30-f47d1e2b5944", "726792f0-72b5-4ae2-b995-5b95d29ccd3f", "86c58f1d-6a0f-4fd4-8dbc-d49fd1db0888"]', '["summary/545e625f-0915-4665-b5a1-d07622997253"]', 'null', NULL, '["法律关系主体类"]', 2, '2026-09-17 02:53:19.790341+00', '2026-09-17 03:09:07.095985+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('15e4c6cd-d38c-40b1-b3a2-83f21227020e', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/chanpin-jiegou-dui-changfuhuneng-de-yingxiang', '产品结构对偿付能力的影响', 'concept', 'published', '# 产品结构对偿付能力的影响

## 一、2025年度偿付能力情况
截至2025年12月31日，小康人寿实际资本343539.94万元，核心资本343109.82万元，最低资本128278.17万元，核心偿付能力充足率为267.47%，综合偿付能力充足率为267.81%，偿付能力充足。

2024年度末对比数据如下：
