INSERT INTO "public"."wiki_pages" VALUES ('eef3f5d7-1e45-45ed-b1d3-9d72e2fbf04c', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'entity/xiaokang-kangxiang-yue-liangquan-baoxian-fenhongxing', '小康康享悦两全保险（分红型）', 'entity', 'published', '# 小康康享悦两全保险（分红型）

## 基本信息
产品类别：人寿保险，产品类型：两全保险，产品设计类型：分红型
已完成备案，主要销售渠道为银行代理渠道和公司直销渠道，目前在售并正常推动。

保险责任：身故保险金、满期保险金
保险期间：趸交为6年，3年交为10年，5年交为15年
缴费方式：趸交、3年交、5年交

## 经营数据
- 2025年度银行代理渠道原保险保费收入排名第一，原保险保费收入为18034.90万元，占银行代理渠道原保险保费收入比例21.64%。
- 2025年度公司直销渠道原保险保费收入排名第三，原保险保费收入为0.20万元，占公司直销渠道原保险保费收入比例0.19%。
- 2025年新单规模保费1.8亿元，占公司新单规模保费比例27.63%，为公司主打产品。
- 主要销售地区前三为上海（1172万元）、北京（692.7万元）、湖南（500万元）。

## 定价与利润测试
### 定价参数假设
预定附加费用率：
| 保单年度 | 趸交 | 3年交 | 5年交 |
| --- | --- | --- | --- |
| 1 | 5.00% | 14.50% | 27.00% |
| 2 | 0.00% | 1.00% | 1.00% |
| 3 | 0.00% | 1.00% | 1.00% |
| 4 | 0.00% | 0.00% | 0.50% |
| 5 | 0.00% | 0.00% | 0.50% |

### 利润测试参数假设
- 退保率假设：期交缴费期内每年5%，趸交或期交缴费期后每年2%。
- 可用费用率假设与预定附加费用率一致。
- 风险贴现率10%，通货膨胀率2.5%，保险保障基金0.30%，监管费0.04%，所得税率25%。
- 件均保费：趸交15万，3年交5万，5年交3万。
- 业务分布假设：
  - 年龄权重：0岁5.0%，10岁5.0%，20岁5.0%，30岁10.0%，40岁40.0%，50岁25.0%，60岁10.0%。
  - 缴费期间权重：趸交20.0%，3年交45.0%，5年交35.0%。
  - 性别权重：男性50%，女性50%。

### 不同情形下利润测试结果
| 情形 | 产品利润率 | 新业务价值率 |
| --- | --- | --- |
| 基础情形 | 3.54% | 4.58% |
| 投资收益率较基础情形增加0.5% | 6.02% | 8.52% |
| 投资收益率较基础情形减少0.5% | 0.92% | 0.65% |
| 死亡率较基础情形上升10% | 3.51% | 4.54% |
| 死亡率较基础情形下降10% | 3.57% | 4.63% |
| 费用率较基础情形上升10% | 3.51% | 4.50% |
| 费用率较基础情形下降10% | 3.57% | 4.67% |
| 退保率较基础情形上升25% | 3.67% | 4.87% |
| 退保率较基础情形下降25% | 3.41% | 4.29% |
| 风险折现率较基础情形增加1% | 3.54% | 4.32% |
| 风险折现率较基础情形减少1% | 3.54% | 4.88% |
| 红利分配比例调整为75% | 3.12% | 3.75% |
| 红利分配比例调整为85% | 2.28% | 1.97% |

利润测试结果符合公司预期。

## 偿付能力相关
在分红型人寿保险中，小康康享悦两全保险（分红型）占整体寿险业务保险风险最低资本的比例为0.82%，该产品在退保率下降情形下产生的最低资本较高。', '介绍小康康享悦两全保险（分红型）的基本属性、经营数据和产品测试信息。', '', '3962aa53-9a7e-4d35-a552-5f14779b18fb', '["保险产品", "两全保险"]', 'entity/保险产品/两全保险/小康康享悦两全保险（分红型）', 2, 0, '["505e896c-5e25-4653-b9c8-12a875db0f51"]', '["1af6c4fa-854a-4131-9a6d-e84d5b059ba0", "140ae2fc-a7cf-48f2-800e-4807eb883cf0", "30eedf35-9c66-4a42-8a9f-32e1526f55dd", "5183f8e6-b0d2-49d8-9e2f-87bf26c95e7f", "e4ef020c-070a-47b6-bb0b-887e0dcaa994", "59d88c1e-3384-49d8-bb50-fdec6b12455a", "00b01d37-4a93-40f4-80d1-c0147f7c78cb", "09509d47-ed33-4bab-93ce-d203d7cbb6ae", "77768f2f-9222-4ed0-8b06-63c17853c7c3", "da41aac9-a269-4644-8b0a-6b0d0e45cbb8", "c8003de8-8e81-4fe8-bbc9-cc6393a61d7e"]', '["summary/505e896c-5e25-4653-b9c8-12a875db0f51", "concept/niandu-chanpin-jingying-celve", "concept/chanpin-jiegou-dui-changfuhuneng-de-yingxiang", "concept/chanpin-dingjia-helixing"]', 'null', NULL, '[]', 1, '2026-09-16 07:28:13.965064+00', '2026-09-16 07:30:35.15847+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('74c26940-4634-47be-85c3-0632aac5187b', 10000, 'eae6cd64-1a52-4012-b52d-a94d9f7de4fa', 'concept/revenue-expenditure-two-line-management', '收支两条线管理', 'concept', 'published', '# 收支两条线管理

收支两条线管理，是指将基金的收入和支出分别纳入不同账户管理、实现收与支分离的基金监管制度。

[[concept/unemployment-insurance|失业保险]]基金必须存入财政部门在国有商业银行开设的社会保障基金财政专户，实行收支两条线管理。该制度由财政部门依法进行监督，目的是保障基金专款专用，防止被挪用和挤占，维护基金安全。', '收支两条线管理是将基金收入与支出分账户管理的监管制度，保障基金专款专用、维护基金安全。', '', '8d956f98-cb8f-482e-802e-70b609f7150f', '["社会保险基金"]', 'concept/社会保险基金/收支两条线管理', 1, 0, '["40b187b1-603c-4bb6-aeb4-717dae40fa21"]', '[]', '["summary/40b187b1-603c-4bb6-aeb4-717dae40fa21", "entity/social-insurance-funds"]', '["concept/unemployment-insurance"]', NULL, '["收支两条线"]', 1, '2026-09-17 05:49:31.189943+00', '2026-09-17 05:50:34.718398+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('d0488054-c1fb-4b25-a65f-75cb3baa6f9c', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'entity/china-insurance-association', '中国保险行业协会', 'entity', 'published', '# 中国保险行业协会

中国保险行业协会是保险行业自律组织，发布保险行业相关配套规则与经验数据。
- 2025年，发布了配套的《保险[[concept/product-appropriateness-management|产品适当性管理]]自律规则（征求意见稿）》，对保险产品销售的适当性管理进行进一步细化。
- 发布了人身保险产品预定利率研究值，用于配合预定利率与市场利率挂钩及动态调整机制相关监管要求。', '本页面更新了中国保险行业协会的性质及发布行业规则与研究数据的相关信息。', '', '2666d85f-4d9a-4a4e-9943-246e2246ab8e', '["组织机构"]', 'entity/组织机构/中国保险行业协会', 1, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["f5a15c80-6261-4ee2-8f37-25a5baf90f2c", "745f6270-4a20-4098-8cf2-d6da874acbad", "42d00d1e-cd5f-4293-9be5-ced4744c673f"]', '["concept/insurance-product-exit"]', '["concept/product-appropriateness-management"]', NULL, '[]', 1, '2026-09-16 08:05:54.008085+00', '2026-09-16 08:07:16.340555+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('bf76d0bf-9946-4387-ae2d-d11cea43c509', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'entity/legal-acts-and-procedures', '法律行为/程序类', 'entity', 'published', '# 法律行为/程序类

法律行为/程序类是法律规范所调整的各类具有法律意义的行为及相关程序的类别总称，涵盖行政、民事等不同领域的法律活动。

## 主要特征
- 该类别指向具有法律意义的活动与程序，而非实体权利义务本身
- 通常由法律、行政法规或规章明确规定其适用条件、程序步骤与法律后果
- 既包括监管机关实施的监管程序，也包括市场主体依法应当履行的程序性义务

## 下属分类方向
- **登记类**：如社会保险登记、失业登记等，由法定主体向经办机构申请办理登记手续，是相关权利义务确立或变更的程序性要件
- **行政许可类**：如保险条款和保险费率审批、保险公司设立审批等，须经监管机关批准后方可实施，适用《中华人民共和国行政许可法》及相关监管规定
- **备案类**：如部分险种保险条款和保险费率备案、失业人员名单备案等，市场主体在经营使用后按规定期限向监管机关报送材料备查
- **认定鉴定类**：如[[concept/work-injury-identification|工伤认定]]、[[concept/labor-ability-appraisal|劳动能力鉴定]]等，由法定机构依申请对特定事实或状态进行确认，是相关待遇享受的前提程序
- **征缴类**：如社会保险费征收与缴纳程序，包括申报、核定、征收、补缴等环节，明确缴费义务履行的法定程序
- **监督检查类**：监管机关对法律法规执行情况、基金收支管理情况等进行监督检查的程序
- **行政处罚类**：监管机关对违反法律、行政法规或规章的行为依法采取的处罚措施
- **救济类**：如行政复议、行政诉讼、劳动争议调解仲裁等，权利受侵害时的救济程序

## 与相关类别的关系
法律行为/程序类侧重于法律活动的过程与程序规则，区别于规定实体权利义务的法律法规本身，也区别于法律文书、法律责任等其他法律相关类别。程序类规则通常与实体规则配套适用，是实体权利义务得以实现或落实的制度保障。', '法律行为/程序类是具有法律意义的行为与法定程序的类别总称，涵盖登记、征缴、认定、监督、处罚等多类程序。', '', '3b540649-7146-4161-92db-8ae80c8b4636', '["法律相关", "程序类别"]', 'entity/法律相关/程序类别/法律行为/程序类', 2, 0, '["09f98df9-1d2e-4e78-942e-827aa98c8340", "48257422-e389-4722-b0c7-f468b15d3b70", "f10d24ba-f395-4ea2-a362-82b161c78439", "545e625f-0915-4665-b5a1-d07622997253", "a80a58b2-6424-4d94-a41a-a97be2e9999e"]', '["c08040d9-0fca-41a6-ae75-c18031d98405", "ca78f84e-1670-427c-99ef-936e764f2613", "4246bd2c-ded0-4e89-99c2-3a9b09f4f600", "cac6932c-8248-47f2-acca-53f483330714", "a8811bde-49c9-4aa7-ac9c-039976cf317f", "7e2bda24-f659-487d-bbf2-0d3c3f22ac21", "065aff8c-31e8-4de2-88f1-90a733cba53c", "8f530b67-c6f3-4ed6-acdc-bbd75a793b25", "b51392f3-2c07-4474-bf28-e70eab159130", "a5f16c8d-e7b2-436b-a170-1ec267cfe818", "17fb92b5-7887-404e-ac6e-78a3f7194888", "15cd894e-0a80-47f2-8fcb-083b4c8d2e49", "08887cab-648a-450e-bb25-2ffcd161de8d", "2f5f8f97-9d75-4da1-ae16-71aad9a4d50b", "fa463282-728f-49b8-8e72-4a1d7b0e059d", "50fd0539-8728-4365-826d-cea981264842", "7a7fc8bd-7338-481b-860b-5f9848525f29", "c12a01b2-61fe-443b-87a9-93190d87e97b", "d091acd8-2b7f-4191-a3a8-c6d4b80e5262", "ccc157cd-9679-4c85-be97-f7374e6dcfe4", "7371094d-5bcd-40d8-8cb4-d78321c23780", "77218531-46ac-46e9-a12f-c679eac2eba9", "53f48886-7da9-406a-a5b3-509fa5b29550", "17c35c9b-977c-447e-85ff-f8d0e5c26319", "56514901-34bb-4bf8-ab79-deb7a2ff52da", "724cbcad-70f4-4672-aaf9-830da3b99529", "ae127986-091e-455c-bcc8-609cc23433a6", "15c24a7b-d9b7-4654-af0d-239b490925b1", "5fde47e7-bb0b-4561-a4a8-57902fad9930", "23fb55ad-3407-4282-a0db-d29a020cc89a", "62638a93-13ab-4db3-8c26-ffd2ba4e5502", "32082345-bb70-4791-83ef-28c0cd3984bc", "014fb38d-7d89-4f5d-9807-da9f4f3e84a4", "f67a7787-29c5-48b2-918c-13baaac6b830", "247cbe13-ed9e-4c85-847b-7ad3cc57d9b9", "e4e88166-483d-4874-9f7a-c063836a83a2", "fa0db3ad-2441-4e0d-8e48-4342c92d5334", "cdb40ffa-cb83-42f5-a3cd-7bf43cff132e", "3aa8b21a-1747