INSERT INTO "public"."wiki_pages" VALUES ('765a41f7-e4a1-4646-81b1-c333d2ffa19d', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/product-appropriateness-management', '产品适当性管理', 'concept', 'published', '# 产品适当性管理
产品适当性管理是针对保险产品销售匹配度的监管要求，对产品进行分类分级管理的制度。

根据监管《金融机构产品适当性管理办法》及行业协会配套规则要求，公司成立专项整改项目组，完成产品分类分级修订，已于2026年2月1日前在官网完成在售产品分类分级信息披露。', '本页面介绍保险行业产品适当性管理的监管要求及小康人寿相关整改工作内容。', '', '1d7fbb26-a97d-49ca-9261-7e84f8177682', '["机构监管"]', 'concept/机构监管/产品适当性管理', 1, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["f5a15c80-6261-4ee2-8f37-25a5baf90f2c"]', '["entity/china-insurance-association", "entity/guojia-jinrong-jiandu-guanli-zongju", "concept/insurance-product-compliance", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', 'null', NULL, '[]', 1, '2026-09-16 08:06:10.225355+00', '2026-09-16 08:07:16.518888+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('561c212d-c81a-48fe-bffe-a230833e5d97', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'concept/consumer-rights-protection-review', '消费者权益保护审查', 'concept', 'published', '# 消费者权益保护审查

消费者权益保护审查，是指对保险条款和费率进行的消费者权益保护方面的审查程序。

在财产保险公司保险条款和保险费率管理中，消费者权益保护审查是条款开发与费率厘定环节的必经内部审查程序：

- 合规负责人在对保险条款进行审查时，应当确认保险条款公平合理，不侵害投保人、被保险人和受益人的合法权益，并已通过消费者权益保护审查。
- 总精算师在对保险费率进行审查时，应当确认保险费率厘定科学准确，满足合理性、公平性和充足性原则，并已通过消费者权益保护审查。', '消费者权益保护审查是保险条款和费率管理中的法定审查环节，由合规负责人与总精算师分别确认通过。', '', 'ec73aafa-c8b7-4240-b043-9ac0eb7f0a61', '["保险监管", "监管程序"]', 'concept/保险监管/监管程序/消费者权益保护审查', 2, 0, '["09f98df9-1d2e-4e78-942e-827aa98c8340"]', '["6a519d6c-2d30-4827-9952-69ba0f039318", "da7ec3f0-3071-4cad-a761-ff740cd73287"]', '["concept/rate-setting-principles"]', 'null', NULL, '["消保审查"]', 1, '2026-09-17 02:53:19.744719+00', '2026-09-17 02:53:54.606988+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('7d21940f-2b65-4ed6-9ede-b0e876c9e7a4', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/personal-insurance-disability-assessment-standard-switch', '人身保险伤残评定标准切换', 'concept', 'published', '# 人身保险伤残评定标准切换

人身保险伤残评定标准切换是指人身保险伤残评定标准从旧标准切换为新标准的工作。

[[entity/state-administration-for-market-regulation|国家市场监督管理总局]]和[[entity/state-administration-of-standardization|国家标准化管理委员会]]联合发布了《人身保险伤残评定及代码》(GB/T 44893-2024)，简称“新国标”，2025年2月1日起正式实施。

为做好新国标切换工作，保险公司针对使用旧标准的意外伤害保险以及含意外伤残责任的其他人身保险产品，在官网发布意外伤残择优理赔公告：2025年2月1日（含）之后的理赔申请，客户可在旧标准与新标准中择优选择伤残评定标准作为赔付依据。

保险公司后续开发的新产品，其伤残或者全残定义均已使用新国标。', '本页面介绍人身保险伤残评定标准切换相关要求、新国标实施及具体实施情况。', '', '1d7fbb26-a97d-49ca-9261-7e84f8177682', '["机构监管"]', 'concept/机构监管/人身保险伤残评定标准切换', 1, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["d7664089-0826-40fe-a12d-228ce1dedb15"]', '["concept/insurance-product-compliance", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', '["entity/state-administration-for-market-regulation", "entity/state-administration-of-standardization"]', NULL, '["新国标切换"]', 1, '2026-09-16 08:06:02.366883+00', '2026-09-16 08:07:16.520495+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('8ff83ffa-89c0-4347-ad0d-d9b54e3072cf', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/insurance-product-structure', '保险产品结构', 'concept', 'published', '# 保险产品结构
保险产品结构指按产品类型、设计类型等维度划分的保险公司在售产品构成。

## [[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年度产品结构特点
### 期初在售产品
期初共17款在售产品：
- 按产品类型划分：人寿保险4款、年金保险2款、健康保险6款、意外伤害保险5款，占比分别为24%、12%、35%、29%；
- 按设计类型划分：普通型16款、万能型1款，占比分别为94%、6%，无在售分红型保险和投资连结型保险。

### 当年新备案产品
当年新备案产品共21款（不含撤回备案1款）：
- 按产品类型划分：人寿保险12款、年金保险8款、健康保险1款，占比分别为57%、38%、5%，无新备案意外伤害保险；
- 按设计类型划分：普通型7款、分红型11款、万能型3款，占比分别为33%、53%、14%，无新备案投资连结型保险。

### 当年停售产品
当年停售产品共12款：
- 按产品类型划分：人寿保险6款、年金保险4款、健康保险2款，占比分别为50%、33%、17%，无意外伤害保险停售；
- 按设计类型划分：普通型9款、分红型2款、万能型1款，占比分别为75%、17%、8%，无投资连结型保险停售。

### 期末在售产品
期末共25款在售产品，其中14款为2025年新备案，11款为往年备案：
- 按产品类型划分：人寿保险9款、年金保险6款、健康保险5款、意外伤害保险5款，占比分别为36%、24%、20%、20%；
- 按设计类型划分：普通型15款、分红型保险8款、万能型2款，占比分别为60%、32%、8%，无在售投资连结型保险。', '本页面介绍保险产品结构的定义，以及小康人寿2025年度不同阶段的产品结构数据。', '', 'e9f282dd-2abf-4b5f-82ea-ab1c326fd97c', '["产品经营", "产品分析"]', 'concept/产品经营/产品分析/保险产品结构', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["a0fa1acf-8761-450d-9722-9ff9a03bac34", "ee1c80c3-0a03-482e-9642-7610df399227", "0f5d4a4b-adbf-4355-b066-8457717dd9b1", "19d0ad4b-eb92-49b0-a133-9f3b8e5761ea"]', 'null', '["entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', NULL, '["产品结构"]', 1, '2026-09-16 08:06:02.095294+00', '2026-09-16 08:07:16.286433+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('40d4b2f5-409e-42fc-89f5-01abe4cb16fa', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/china-life-insurance-experience-mortality-table-2010-2013', '中国人身保险业经验生命表（2010—2013）', 'concept', 'published', '# 中国人身保险业经验生命表（2010—2013）
中国人身保险业经验生命表（2010—2013）是行业发布的人身保险死亡率参考标准表，是保险公司产品定价的基础。

该生命表包含以下细分表：
- CL1/CL2(2010-2013)：分别为非养老类业务一表（男）/（女）
- CL3/CL4(2010-2013)：分别为非养老类业务二表（男）/（女）
- CL5/CL6(2010-2013)：分别为养老类业务表（男）/（女）

保险公司在产品定价中会以该生命表为基础，结合自身经验设定发生率假设，发生率的使用需符合[[entity/guojia-jinrong-jiandu-guanli-zongju|国家金融监督管理总局]]的相关规定。根据[[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年度产品回溯，其长期寿险产品定价普遍采用不同乘数的该生命表作为死亡发生率基础，例如80%*CL5/CL6(2010-2013)、80%*CL3/CL4(2010-2013)等。

小康人寿2025年度产品回溯中，公司整体死亡实际赔付占按100%该生命表计算的死亡预期赔付比例为16.46%，实际/预期赔付率较低，主要原因为业务重启后承保时间短、暴露样本容量不充分，且储蓄型业务占比较高。各产品线实际/预期赔付率情况如下：
| 产品线 | 死亡实际赔付（万元） | 死亡预期赔付（万元） | 实际/预期赔付率（%） |
| ---- | ---- | ---- | ---- |
| 两全保险 | 328.49 | 2553.91 | 12.86 |
| 定期寿险 | - | - | —— |
| 终身寿险 | 274.07 | 921.15 | 29.75 |
| 普通年金 | -10.74 | 17.23 | -62.36 |
| 养老年金 | - | 96.48 | 0.00 |
| 疾病保险 | - | 6.40 | 0.00 |
| 公司整体 | 591.82 | 3595.17 | 16.46 |

各销售渠道实际/预期赔付率情况如下：
| 渠道 | 死亡实际赔付（万元） | 死亡预期赔付（万元） | 实际/预期赔付率（%） |
| ---- | ---- | ---- | ---- |
| 银行代理渠道 | 398.37 | 3111.62 | 12.80 |
| 公司直销渠道 | - | 1.01 | 0.00 |
| 中介代理渠道 | 193.45 | 482.51 | 40.09 |
| 互联网代理渠道 | - | 0.035 | 0.00 |
| 公司整体 | 591.82 | 3595.17 | 16.46 |', '本页面介绍中国人身保险业经验生命表（2010—2013）的构成及行业应用情况。', '', '31e37bb2-6b60-4f82-b6ca-d9bdeb6b98bf', '["保险产品", "寿险产品"]', 'concept/保险产品/寿险产品/中国人身保险业经验生命表（2010—2013）', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["d2e05837-fef7-4c71-96da-1642e3d83df6", "7a5393b5-a873-4dd9-91c8-e172aadbfb7d", "a60252a8-121f-47f7-99f6-dfeafaffb8db", "6a6bee55-f12d-4d15-a76e-e19344904227", "4c85594a-6d94-41cc-af8e-bf0148e4ac0b", "80678a8a-e434-4b33-b6e4-8b6b47d1718b"]', '["concept/expected-incidence-rate-backtracking", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', '["entity/guojia-jinrong-jiandu-guanli-zongju", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', NULL, '["CL1/CL2/CL3/CL4/CL5/CL6(2010-2013)"]', 1, '2026-09-16 08:06:04.48127+00', '2026-09-16 08:07:16.530389+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('644961ac-6539-4f49-af08-9a9bd2ea842e', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/combined-reporting-and-implementation', '报行合一', 'concept', 'published', '# 报行合一
报行合一是保险行业监管要求保险公司报送的条款费率与实际执行一致的制度。

报行合一后，产品附加费用率即利润测试时的可用总费用水平。从小康人寿整体来看，2025年存量业务精算可用费用可以完全覆盖销售费用，略低于销售费用及与销售相关的管理费用之和，暂不能覆盖实际费用。实际费用高于精算可用费用的主要原因：一方面公司整体业务规模较小，未实现规模效应，无法摊薄职场费用、内勤人力费用、资产使用费用和IT费用等管理费用；另一方面存量业务中包含了较多已停售的报行合一前产品的续期业务，这部分续期业务存在续年预定附加费用率较低甚至为0，续年可用总费用无法覆盖管理费用。随着业务发展和报行合一的持续贯彻执行，实际/可用费用率将下降。

从产品线来看，小康人寿人寿保险、年金保险和健康保险（销售+与销售相关的管理费用）/可用费用率分别为 109.07%、94.54%、143.65%，销售/可用费用率分别为82.83%、87.90%和108.48%。

小康人寿将贯彻执行报行合一政策，为有效控制并降低实际/可用费用率，制定了相关工作计划：一是扩大业务规模，优化业务结构。聚焦核心产品与优势渠道，加大市场拓展力度，提升业务保费规模，优化业务结构，逐步摊薄职场、内勤人力、资产使用及IT等管理费用。二是强化费用管控，优化费用结构。优化销售费用配置，进一步梳理销售费用结构，提升销售费用投产效能；严格把控管理费用支出，建立精细化费用管理体系，对职场费用、内勤人力费用、资产使用费用、IT费用等管理费用进行分类管控，压缩非必要支出，提高费用使用效率。同时，持续关注渠道和产品线的费用支出情况，提高公司费用管理水平，适时对费用假设进行适当调整，以真实反映公司实际经营情况。

在公司下一步工作计划中，小康人寿明确提出要坚定执行报行合一政策，提高公司费用管理水平，加强产品在不同渠道的精细化、科学化管理。', '本页面介绍保险监管要求的报行合一制度及其对小康人寿的实际影响。', '', '1d7fbb26-a97d-49ca-9261-7e84f8177682', '["机构监管"]', 'concept/机构监管/报行合一', 1, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["db9461df-231c-4f81-b826-0c331a432e23", "0c49ff01-8ed8-4cca-8c53-b6a45ca552c2", "8f8cb659-059b-42a2-9383-74da85a2f277", "17c0f7c1-bf17-4cb2-992c-315407766e3f"]', '["concept/pricing-backtracking-analysis", "concept/expense-rate-backtracking", "concept/insurance-product-operation", "concept/insurance-product-backtracking", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', 'null', NULL, '[]', 1, '2026-09-16 08:06:01.680669+00', '2026-09-16 08:07:16.514726+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('8095d3b4-2983-4ff6-a07e-5d74f316c952', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/china-life-insurance-critical-illness-incidence-table-2020', '中国人身保险业重大疾病经验发生率表（2020）', 'concept', 'published', '# 中国人身保险业重大疾病经验发生率表（2020）
中国人身保险业重大疾病经验发生率表（2020），也简称CI4表，是行业发布的重大疾病发生率参考标准表，是保险公司重疾产品定价的基础。

根据[[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年度产品回溯报告，小康人寿在售的[[entity/xiaokang-kangweizhi-zhenxiangban-critical-illness-insurance|小康康卫士（臻享版）重大疾病保险]]和[[entity/xiaokang-kangweishou-shouhuban-zhongdajibing-baoxian-hulianwang|小康康卫士（守护版）重大疾病保险（互联网）]]两款长期重疾产品，定价和利润测试重疾发生率以该表CI4表为基础。

2025年小康人寿公司整体重疾实际赔付占按100%该表计算的重疾预期赔付比例为101.47%，实际/预期赔付率略高于100%，主要因当时长期重疾非公司主售险种，样本容量较小，分散效应弱，对公司财务影响有限。
发生率的使用符合[[entity/guojia-jinrong-jiandu-guanli-zongju|国家金融监督管理总局]]的相关规定。', '本页面介绍中国人身保险业重大疾病经验发生率表（2020）的基本信息及行业使用案例。', '', 'c07a620d-6819-4992-810b-9760fd6265fa', '["保险产品", "重疾险产品"]', 'concept/保险产品/重疾险产品/中国人身保险业重大疾病经验发生率表（2020）', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["af2e3181-2c8d-40a8-81dc-82b9dfc3c464", "685e5dcf-072c-47db-93c4-16874eacfed1", "ca9bc3ce-37d0-4d1e-980a-0edc7cc3e3bb"]', '["entity/xiaokang-kangweizhi-zhenxiangban-critical-illness-insurance", "concept/expected-incidence-rate-backtracking", "entity/xiaokang-kangweishou-shouhuban-zhongdajibing-baoxian-hulianwang", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', '["entity/xiaokang-shouxian-baoxian-youxian-zere-gs", "entity/xiaokang-kangweizhi-zhenxiangban-critical-illness-insurance", "entity/xiaokang-kangweishou-shouhuban-zhongdajibing-baoxian-hulianwang", "entity/guojia-jinrong-jiandu-guanli-zongju"]', NULL, '["CI4表"]', 1, '2026-09-16 08:06:08.927961+00', '2026-09-16 08:07:16.535858+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('d2d9713e-16ed-4c4d-8934-5cf20d74dafb', 10000, 'eae6cd64-1a52-4012-b52d-a94d9f7de4fa', 'concept/solvency-regulation', '偿付能力监管', 'concept', 'published', '# 偿付能力监管

偿付能力监管是保险监管机构对保险公司偿付能力实施监控和管理的制度，旨在保障被保险人利益。

## 基本要求
保险公司应当具有与其业务规模和风险程度相适应的最低偿付能力。保险公司的认可资产减去认可负债的差额不得低于国务院保险监督管理机构规定的数额；低于规定数额的，应当按照国务院保险监督管理机构的要求采取相应措施达到规定的数额。

## 偿付能力保障制度
1. **保证金**：保险公司应当按照其注册资本总额的百分之二十提取保证金，存入国务院保险监督管理机构指定的银行，除公司清算时用于清偿债务外，不得动用。
2. **责任准备金**：保险公司应当根据保障被保险人利益、保证偿付能力的原则，提取各项责任准备金。保险公司提取和结转责任准备金的具体办法，由国务院保险监督管理机构制定。
3. **公积金**：保险公司应当依法提取公积金。
4. **保险保障基金**：保险公司应当缴纳保险保障基金。保险保障基金应当集中管理，并在下列情形下统筹使用：
   - 在保险公司被撤销或者被宣告破产时，向投保人、被保险人或者受益人提供救济；
   - 在保险公司被撤销或者被宣告破产时，向依法接受其人寿[[concept/insurance-contract|保险合同]]的保险公司提供救济；
   - 国务院规定的其他情形。
   保险保障基金筹集、管理和使用的具体办法，由国务院制定。
5. **自留保险费限制**：经营财产保险业务的保险公司当年自留保险费，不得超过其实有资本金加公积金总和的四倍。
6. **危险单位限制**：保险公司对每一危险单位，即对一次保险事故可能造成的最大损失范围所承担的责任，不得超过其实有资本金加公积金总和的百分之十；超过的部分应当办理再保险。保险公司对危险单位的划分应当符合国务院保险监督管理机构的规定。

## 监管体系与措施
国务院保险监督管理机构应当建立健全保险公司偿付能力监管体系，对保险公司的偿付能力实施监控。

对偿付能力不足的保险公司，国务院保险监督管理机构应当将其列为重点监管对象，并可以根据具体情况采取下列措施：
1. 责令增加资本金、办理再保险；
2. 限制业务范围；
3. 限制向股东分红；
4. 限制固定资产购置或者经营费用规模；
5. 限制资金运用的形式、比例；
6. 限制增设分支机构；
7. 责令拍卖不良资产、转让保险业务；
8. 限制董事、监事、高级管理人员的薪酬水平；
9. 限制商业性广告；
10. 责令停止接受新业务。

## 整顿与接管
### 整顿
保险公司未依照本法规定提取或者结转各项责任准备金，或者未依照本法规定办理再保险，或者严重违反本法关于资金运用的规定的，由保险监督管理机构责令限期改正，并可以责令调整负责人及有关管理人员。

保险监督管理机构依照前款规定作出限期改正的决定后，保险公司逾期未改正的，国务院保险监督管理机构可以决定选派保险专业人员和指定该保险公司的有关人员组成整顿组，对公司进行整顿。整顿决定应当载明被整顿公司的名称、整顿理由、整顿组成员和整顿期限，并予以公告。

整顿组有权监督被整顿保险公司的日常业务。被整顿公司的负责人及有关管理人员应当在整顿组的监督下行使职权。整顿过程中，被整顿保险公司的原有业务继续进行。但是，国务院保险监督管理机构可以责令被整顿公司停止部分原有业务、停止接受新业务，调整资金运用。

被整顿保险公司经整顿已纠正其违反本法规定的行为，恢复正常经营状况的，由整顿组提出报告，经国务院保险监督管理机构批准，结束整顿，并由国务院保险监督管理机构予以公告。

### 接管
保险公司有下列情形之一的，国务院保险监督管理机构可以对其实行接管：
1. 公司的偿付能力严重不足的；
2. 违反本法规定，损害社会公共利益，可能严重危及或者已经严重危及公司的偿付能力的。

被接管的保险公司的债权债务关系不因接管而变化。

接管组的组成和接管的实施办法，由国务院保险监督管理机构决定，并予以公告。接管期限届满，国务院保险监督管理机构可以决定延长接管期限，但接管期限最长不得超过二年。接管期限届满，被接管的保险公司已恢复正常经营能力的，由国务院保险监督管理机构决定终止接管，并予以公告。

## 破产与撤销
被整顿、被接管的保险公司有《中华人民共和国企业破产法》第二条规定情形的，国务院保险监督管理机构可以依法向人民法院申请对该保险公司进行重整或者破产清算。

保险公司因违法经营被依法吊销经营保险业务许可证的，或者偿付能力低于国务院保险监督管理机构规定标准，不予撤销将严重危害保险市场秩序、损害公共利益的，由国务院保险监督管理机构予以撤销并公告，依法及时组织清算组进行清算。

## 其他监管措施
国务院保险监督管理机构有权要求保险公司股东、实际控制人在指定的期限内提供有关信息和资料。

保险公司的股东利用关联交易严重损害公司利益，危及公司偿付能力的，由国务院保险监督管理机构责令改正。在按照要求改正前，国务院保险监督管理机构可以限制其股东权利；拒不改正的，可以责令其转让所持的保险公司股权。', '偿付能力监管是保险监管机构对保险公司偿付能力实施监控和管理的制度，涵盖最低偿付能力要求、监管措施及整顿接管等内容。', '', 'c8a862d8-85d4-49bf-9d1e-5b9e5135cdcc', '["保险监管"]', 'concept/保险监管/偿付能力监管', 1, 0, '["68ee7396-a2d6-4807-8cbd-d3fd4fd5fb19"]', '["ef8da381-4404-4634-bf00-d18123e612c4", "f796cce8-c812-4d60-a4a6-155203e8d69b", "e67b35a9-48a4-41b3-af41-6e3ff2e5c2ca", "1277e3d1-b10a-4783-b7c7-fb5d2a66fe18", "55e1a297-7126-47a5-bdf7-37013d285e36", "31578f29-859a-471a-a5eb-98cb6a6313ad", "ce25c2be-8b21-4b47-9f2b-2f8f57ba5e13"]', '["summary/68ee7396-a2d6-4807-8cbd-d3fd4fd5fb19"]', '["concept/insurance-contract"]', NULL, '["偿付能力管理"]', 1, '2026-09-17 05:49:32.393852+00', '2026-09-17 05:50:34.822338+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('0d8fd8f9-a40f-49af-bfb1-e68e697b79af', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/insurance-product-compliance', '保险产品合规', 'concept', 'published', '# 保险产品合规

保险产品合规指保险产品开发、销售、条款费率等环节符合监管规则要求的情况。

## 总体制度建设
企业产品开发管理机制需健全，应当建立相应的产品开发管理制度。以[[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年实践为例：
1. 产品开发管理制度包含《产品委员会议事规则》《产品开发及管理办法》《产品开发及管理工作实施细则》三个文件。其中《产品委员会议事规则》明确了产品委员会作为产品开发和管理专业议事机构，规定了产品委员会的组织架构、工作职责、工作流程及议事规则；《产品开发及管理办法》《产品开发及管理工作实施细则》从工作原则、工作职责、产品规划、产品需求、产品定价、产品上线与上市、产品售后管理等方面加强和规范产品开发及管理工作，确保产品开发及管理工作科学、有序、高效、合规地开展。
2. 2025年，小康人寿对《产品委员会议事规则》和《产品开发及管理办法》进行了修订，同时将原《产品开发及管理工作实施细则》并入《产品开发及管理办法》。新制度修订有助于进一步科学制定产品发展策略、有效决策产品方向及产品计划，加强和规范公司产品开发及管理工作。
3. 产品开发严格按照外部监管要求和内部文件规定执行，费率厘定满足合理性、充足性、适当性和公平性原则；产品条款满足公平性、合理性和合规性要求。
4. 2025年，小康人寿未出现因产品条款或者费率引发的诉讼案例，经过自查，未发现备案产品存在违法违规或显失公平的情形，当年新备案的21款产品均已顺利予以备案。

## 监管要求自查整改
根据监管要求，保险企业需开展针对性自查整改：
1. **[[concept/product-appropriateness-management|产品适当性管理]]**：根据《金融机构产品适当性管理办法》及行业协会配套规则要求，企业应当成立专项整改项目组，完成产品分类分级修订，并在规定时限前在官网完成在售产品分类分级信息披露。小康人寿已于2026年2月1日前完成该项工作。
2. **[[concept/personal-insurance-disability-assessment-standard-switch|人身保险伤残评定标准切换]]**：配合[[entity/state-administration-for-market-regulation|国家市场监督管理总局]]和[[entity/state-administration-of-standardization|国家标准化管理委员会]]发布的《人身保险伤残评定及代码》（GB/T 44893-2024，新国标）实施，企业需在官网发布意外伤残择优理赔公告，适用所有使用旧标准的意外险及含意外伤残责任的产品，实施日后理赔可择优选择评定标准，后续新产品已全部使用新国标。', '本页面介绍保险产品合规的定义，结合小康人寿2025年实践说明相关制度建设与监管整改情况。', '', '1d7fbb26-a97d-49ca-9261-7e84f8177682', '["机构监管"]', 'concept/机构监管/保险产品合规', 1, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["a0fa1acf-8761-450d-9722-9ff9a03bac34", "b4c6afc1-a8f5-483a-bf09-30b5f00bfa0e", "8f9a0a8e-5ca0-44d3-9f6d-0c84d3effc8f", "f5a15c80-6261-4ee2-8f37-25a5baf90f2c"]', 'null', '["entity/xiaokang-shouxian-baoxian-youxian-zere-gs", "concept/product-appropriateness-management", "concept/personal-insurance-disability-assessment-standard-switch", "entity/state-administration-for-market-regulation", "entity/state-administration-of-standardization"]', NULL, '["产品合规"]', 1, '2026-09-16 08:06:06.522665+00', '2026-09-16 08:07:16.319213+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('6368f6b9-6de4-4a21-92ba-42bd88da55dd', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/insurance-product-exit', '保险产品退出', 'concept', 'published', '# 保险产品退出

**保险产品退出**：保险产品停止销售退出市场的相关情况

## [[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年度产品退出情况
2025年，小康人寿共有12款产品退市。产品退市主要原因为根据公司业务发展规划，结合人身保险产品预定利率研究值主动停售。

### 因销售未达标退市情况
备案满一年的个人产品（剔除短期健康保险和意外伤害保险）中，无因年度累计保费收入少于100万且年度累计销售件数少于5000件而退市的产品。

### 因其他原因退市情况
根据《关于建立预定利率与市场利率挂钩及动态调整机制有关事项的通知》，结合市场利率变化及[[entity/china-insurance-association|中国保险行业协会]]发布的人身保险产品预定利率研究值，小康人寿于2025年9月1日前主动停售：
- 9款预定利率超过2.0%普通型保险产品
- 2款预定利率超过1.75%的分红型保险产品
- 1款最低保证利率超过1.0%的万能型保险产品

### 产品退市合规性
产品退市严格执行[[entity/guojia-jinrong-jiandu-guanli-zongju|国家金融监督管理总局]]相关文件和公司内部相关制度规定。2025年停售的12款产品均按照相关工作机制和流程进行产品停售，并按照监管要求，向国家金融监督管理总局报送停售报告以及完成相关信息披露工作。

产品停售后，持有停售产品保单的客户享有的各项权益不受影响，公司将继续为其提供保全、理赔等服务。

2025年退市产品清单参见附表2。', '本文介绍保险产品退出的概念，并以小康人寿2025年产品退出情况为例说明相关规则。', '', '43bc17fd-0d26-483e-8851-4c805acdb897', '["产品经营", "业务经营"]', 'concept/产品经营/业务经营/保险产品退出', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["a0fa1acf-8761-450d-9722-9ff9a03bac34", "6750fd0c-94bb-43e5-8ff1-c80167d0e6cf", "42d00d1e-cd5f-4293-9be5-ced4744c673f", "0c49ff01-8ed8-4cca-8c53-b6a45ca552c2", "55156752-1b0a-44ac-9d5a-100d06af16e6", "fe25d198-2f13-41c0-b157-b208c8efa035"]', 'null', '["entity/xiaokang-shouxian-baoxian-youxian-zere-gs", "entity/china-insurance-association", "entity/guojia-jinrong-jiandu-guanli-zongju"]', NULL, '["产品退市", "产品停售"]', 1, '2026-09-16 08:06:08.356515+00', '2026-09-16 08:07:16.336228+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('0089b8b1-41d7-41da-b784-bc853f8d57d6', 10000, 'eae6cd64-1a52-4012-b52d-a94d9f7de4fa', 'concept/social-insurance-benefits', '社会保险待遇', 'concept', 'published', '# 社会保险待遇

社会保险待遇是指参保人员符合法定条件时可享受的物质帮助待遇，涵盖各险种对应的待遇类型。

社会保险待遇包括基本养老金、医疗费用报销、工伤保险待遇、[[concept/unemployment-insurance|失业保险]]金、生育保险待遇等。不同险种的待遇享受条件、支付标准、资金来源各不相同，由社会保险经办机构负责按时足额支付。

待遇水平会根据经济社会发展情况适时调整，保障参保人员的基本生活与医疗需求。', '介绍社会保险待遇的定义、涵盖类型、享受条件、支付主体及待遇水平调整原则。', '', 'ec48b124-f255-4516-8e40-e0699ca2078c', '["社会保险"]', 'concept/社会保险/社会保险待遇', 1, 0, '["04d520f5-327c-4a02-bb51-3dbfbbdf29c4"]', '[]', '["summary/04d520f5-327c-4a02-bb51-3dbfbbdf29c4", "entity/social-insurance-funds", "entity/legal-actions-procedures", "concept/social-insurance-handling-services"]', '["concept/unemployment-insurance"]', NULL, '["社保待遇"]', 1, '2026-09-17 05:49:35.406356+00', '2026-09-17 05:50:34.846619+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('5d3fe7c9-6315-44b6-8102-b6ba29ec6d8f', 10000, 'eae6cd64-1a52-4012-b52d-a94d9f7de4fa', 'concept/unemployment-insurance-benefits', '失业保险待遇', 'concept', 'published', '# [[concept/unemployment-insurance|失业保险]]待遇

失业保险待遇是失业人员在失业期间依法可享受的各项物质帮助的总称，涵盖失业保险金等多项内容。

失业保险待遇包括失业保险金、医疗补助金、丧葬补助金、抚恤金、职业培训和职业介绍补贴等。待遇领取有明确的条件、期限和标准，停止领取的情形也有法定规定。待遇标准通常低于当地最低工资标准、高于城市居民最低生活保障标准，由省级政府确定。', '失业保险待遇是失业人员失业期间依法享有的各项物质帮助总称，涵盖多项待遇及领取条件、期限、标准与停止情形。', '', '877e92a1-9820-4a4c-b6d9-2655a17f61e6', '["失业保险"]', 'concept/失业保险/失业保险待遇', 1, 0, '["40b187b1-603c-4bb6-aeb4-717dae40fa21"]', '[]', '["summary/40b187b1-603c-4bb6-aeb4-717dae40fa21", "entity/legal-liabilities"]', '["concept/unemployment-insurance"]', NULL, '["失业待遇"]', 1, '2026-09-17 05:49:36.200246+00', '2026-09-17 05:50:34.88788+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('0915853e-cf3e-4aa3-96f8-34686a96d06d', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'concept/insurance-fund-utilization', '保险资金运用', 'concept', 'published', '# 保险资金运用

保险资金运用，是指保险公司将自有资金及保险准备金按规定形式进行投资运用的经营活动。

## 基本原则
保险公司的资金运用必须稳健，遵循安全性原则。

## 资金运用形式
保险公司的资金运用限于下列形式：
（一）银行存款；
（二）买卖债券、股票、证券投资基金份额等有价证券；
（三）投资不动产；
（四）国务院规定的其他资金运用形式。

保险公司资金运用的具体管理办法，由国务院保险监督管理机构依照上述规定制定。

## 保险资产管理公司
经国务院保险监督管理机构会同国务院证券监督管理机构批准，保险公司可以设立保险资产管理公司。

保险资产管理公司从事证券投资活动，应当遵守《中华人民共和国证券法》等法律、行政法规的规定。

保险资产管理公司的管理办法，由国务院保险监督管理机构会同国务院有关部门制定。', '介绍保险资金运用的定义、基本原则、法定运用形式及保险资产管理公司的设立要求。', '', 'e4c73d30-779c-4bac-a89f-ec486eb68f02', '["保险监管", "监管制度"]', 'concept/保险监管/监管制度/保险资金运用', 2, 0, '["f10d24ba-f395-4ea2-a362-82b161c78439"]', '["cd778d07-bf74-42c1-b9f4-cd43ef05a35b", "91a5571f-c8d3-4700-98c7-8a300caaf79b"]', 'null', 'null', NULL, '["保险资金运营"]', 1, '2026-09-17 03:08:51.164005+00', '2026-09-17 03:09:49.653411+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('5651d0d1-9f6b-4d06-b4aa-f61711e55a21', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'summary/48257422-e389-4722-b0c7-f468b15d3b70', '失业保险条例_30733367.pdf - Summary', 'summary', 'published', '## 概述
《失业保险条例》于1998年12月26日国务院第11次常务会议通过，1999年1月22日中华人民共和国国务院令第258号发布，自发布之日起施行。该条例属于[[entity/laws-and-regulations|法律法规类]]，旨在保障失业人员失业期间的基本生活，促进其再就业，是我国[[concept/unemployment-insurance|失业保险]]制度的核心行政法规。

## 第一章 总则
### 适用范围
- 缴费主体：城镇企业事业单位、城镇企业事业单位职工依照本条例规定缴纳[[concept/unemployment-insurance-premium|失业保险费]]。其中城镇企业指国有企业、城镇集体企业、外商投资企业、城镇私营企业以及其他城镇企业。
- 待遇享受主体：城镇企业事业单位失业人员依照本条例规定享受[[concept/unemployment-insurance-benefits|失业保险待遇]]。

### 管理体制
- 国务院劳动保障行政部门主管全国的失业保险工作，属于[[entity/regulatory-agencies|监管机构类]]范畴。
- 县级以上地方各级人民政府劳动保障行政部门主管本行政区域内的失业保险工作。
- 劳动保障行政部门按照国务院规定设立的经办失业保险业务的社会保险经办机构具体承办失业保险工作。

## 第二章 失业保险基金
### 基金构成
[[entity/social-insurance-funds|社会保险基金类]]下的失业保险基金由以下各项构成：
1. 城镇企业事业单位、城镇企业事业单位职工缴纳的失业保险费；
2. 失业保险基金的利息；
3. 财政补贴；
4. 依法纳入失业保险基金的其他资金。

### 缴费标准
- 城镇企业事业单位按照本单位工资总额的2%缴纳失业保险费。
- 城镇企业事业单位职工按照本人工资的1%缴纳失业保险费。
- 城镇企业事业单位招用的农民合同制工人本人不缴纳失业保险费。

### 统筹与调剂
- 失业保险基金在直辖市和设区的市实行全市统筹；其他地区的统筹层次由省、自治区人民政府规定，属于[[concept/unemployment-insurance-coordination|失业保险统筹]]范畴。
- 省、自治区可以建立失业保险调剂金，以统筹地区依法应当征收的失业保险费为基数，按规定比例筹集。统筹地区失业保险基金不敷使用时，由调剂金调剂、地方财政补贴。

### 基金支出与管理
- **支出范围**：包括失业保险金、领取期间的医疗补助金、死亡失业人员的丧葬补助金和抚恤金、职业培训与职业介绍补贴等。
- **管理要求**：失业保险基金存入财政部门在国有商业银行开设的社会保障基金财政专户，实行[[concept/separate-management-of-revenue-and-expenditure|收支两条线管理]]，专款专用，不得挪作他用，不得用于平衡财政收支。

## 第三章 失业保险待遇
### 领取条件
失业人员同时满足以下条件可领取失业保险金：
1. 按照规定参加失业保险，所在单位和本人已履行缴费义务满1年；
2. 非因本人意愿中断就业；
3. 已办理失业登记，并有求职要求。

### 停止领取情形
失业人员在领取失业保险金期间出现下列情形之一的，停止领取并停止享受其他失业保险待遇：
1. 重新就业；
2. 应征服兵役；
3. 移居境外；
4. 享受基本养老保险待遇；
5. 被判刑收监执行或者被劳动教养；
6. 无正当理由拒不接受指定部门或机构介绍的工作；
7. 法律、行政法规规定的其他情形。

### 待遇标准
- **领取期限**：根据累计缴费时间确定，最长不超过24个月；重新就业后再次失业的，缴费时间重新计算，领取期限可与前次未领取期限合并计算，最长不超过24个月。
- **金标准**：低于当地最低工资标准、高于城市居民最低生活保障标准，由省级人民政府确定。
- **其他待遇**：包括医疗补助金、丧葬补助金和抚恤金、农民合同制工人一次性生活补助等，具体标准由省级人民政府规定。

### 关系转迁
城镇企业事业单位成建制跨统筹地区转移、失业人员跨统筹地区流动的，失业保险关系随之转迁，相关程序属于[[entity/legal-acts-and-procedures|法律行为/程序类]]。

## 第四章 管理和监督
### 部门职责
- **劳动保障行政部门**：贯彻实施失业保险法律法规、指导经办机构工作、监督检查失业保险费征收和待遇支付。
- **社会保险经办机构**：负责失业人员登记调查统计、基金管理、待遇核定与发放、补贴拨付、免费咨询服务等。
- **财政与审计部门**：依法对失业保险基金的收支、管理情况进行监督。

### 经费保障
社会保险经办机构所需经费列入预算，由财政拨付。

## 第五章 罚则
本章内容属于[[entity/legal-liabilities|法律责任类]]，主要包括：
1. 骗取失业保险待遇的，责令退还，情节严重的处骗取金额1倍以上3倍以下罚款。
2. 经办机构工作人员违规开具单证造成基金损失的，责令追回，情节严重的给予行政处分。
3. 劳动保障行政部门和经办机构工作人员滥用职权等造成基金损失的，追回基金，构成犯罪的追究刑事责任，尚不构成犯罪的给予行政处分。
4. 挪用失业保险基金的，追回基金，没收违法所得，构成犯罪的追究刑事责任，尚不构成犯罪的对相关人员给予行政处分。

## 第六章 附则
- 省、自治区、直辖市人民政府可根据当地实际情况，决定本条例适用于本行政区域内的社会团体及其专职人员、民办非企业单位及其职工、有雇工的城镇个体工商户及其雇工。
- 本条例自发布之日起施行，1993年4月12日国务院发布的《国有企业职工待业保险规定》同时废止。

## 要点总结
- 《失业保险条例》是我国失业保险制度的核心行政法规，明确了制度的目的、适用范围和管理体制。
- 失业保险基金由单位和个人缴费、利息、财政补贴等构成，实行收支两条线管理，专款专用。
- 失业保险待遇的领取需满足缴费满1年、非因本人意愿中断就业、已办理失业登记并有求职要求三个条件。
- 失业保险金领取期限根据累计缴费时间确定，最长不超过24个月，标准由省级人民政府确定。
- 条例明确了劳动保障行政部门、经办机构、财政审计部门的职责，以及各类违法行为的法律责任。', '《失业保险条例》规范失业保险制度，明确基金构成、待遇标准、管理监督及法律责任。', '', '', '[]', 'summary/失业保险条例_30733367.pdf - Summary', 0, 0, '["48257422-e389-4722-b0c7-f468b15d3b70"]', '[]', 'null', '["entity/laws-and-regulations", "concept/unemployment-insurance", "concept/unemployment-insurance-premium", "concept/unemployment-insurance-benefits", "entity/regulatory-agencies", "entity/social-insurance-funds", "concept/unemployment-insurance-coordination", "concept/separate-management-of-revenue-and-expenditure", "entity/legal-acts-and-procedures", "entity/legal-liabilities"]', NULL, '[]', 1, '2026-09-17 03:08:51.528222+00', '2026-09-17 03:09:49.656628+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('6fe7bc55-5a1b-4f27-ae44-d7fbaf3c3a8a', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'entity/insurance-funds', '保险基金类', 'entity', 'published', '# 保险基金类

## 定义
保险基金类是指用于工伤保险待遇支付等用途的专项基金类别，涵盖工伤保险基金及其储备金。

## 构成
保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。

## 主要特征
1. **专款专用**：基金存入社会保障基金财政专户，用于规定的工伤保险待遇、[[concept/labor-ability-appraisal|劳动能力鉴定]]、工伤预防的宣传培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。
2. **储备金制度**：基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。
3. **用人单位单方缴费**：职工个人不缴纳工伤保险费，用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。

## 费率确定机制
工伤保险费根据以支定收、收支平衡的原则确定费率。
- 国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。
- 统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。
- 国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。

## 统筹管理
工伤保险基金逐步实行省级统筹。跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。

## 监督管理
- 经办机构按照规定管理工伤保险基金的支出，定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。
- 社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。
- 财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。
- 任何组织和个人对有关工伤保险的违法行为，有权举报。', '保险基金类是用于工伤保险待遇支付等用途的专项基金类别，涵盖工伤保险基金及其储备金，具有专款专用的特征。', '', '475b2993-6047-4b6d-9fcb-c7fca6dd92eb', '["社会保险", "工伤保险"]', 'entity/社会保险/工伤保险/保险基金类', 2, 0, '["545e625f-0915-4665-b5a1-d07622997253"]', '["9ef25eb8-93ae-4a07-a422-5443ea886118", "f79533d7-42b5-4fbd-8414-c468cf598734", "af1b16fc-4ec7-4f38-a581-285c5f0488ee", "77a2b7ee-8a55-414c-b21e-779481adde4c", "4c593259-aeff-4909-b19e-73879f24434d"]', '["entity/social-insurance-funds"]', '["concept/labor-ability-appraisal"]', NULL, '["工伤保险基金类"]', 1, '2026-09-17 03:09:31.083528+00', '2026-09-17 03:10:16.638607+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('255740d4-746c-48dd-a99c-b9f374161b24', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'entity/legal-documents', '法律文书类', 'entity', 'published', '# 法律文书类

法律文书类是具有法律效力或法律意义的文书类别的总称，涵盖各类具有法律意义的文件与文书。

## 涵盖范围

### 保险监管领域
财产保险公司报送保险条款和保险费率审批或者备案时，需提交的法律文书类材料主要包括：
- 申请文件
- 保险条款和保险费率文本
- 可行性报告
- 保险费率精算报告
- 法律审查声明书
- 精算审查声明书
- 监管机构规定的其他材料

### [[concept/unemployment-insurance|失业保险]]领域
失业保险事务中涉及的法律文书类材料主要包括：
- 终止或者解除劳动关系的证明
- 领取失业保险金的单证
- 失业保险基金收支的预算、决算

### 工伤保险领域
工伤保险事务中涉及的法律文书类材料主要包括：
- [[concept/work-injury-identification|工伤认定]]申请表
- 与用人单位存在劳动关系的证明材料
- 医疗诊断证明或者职业病诊断证明书（或者职业病诊断鉴定书）', '法律文书类是具有法律效力或法律意义的文书总称，涵盖保险监管、失业保险、工伤保险等领域的多种文书类型。', '', 'b3c71ccf-0734-4eb9-ba36-21157fffb28c', '["法律相关", "文书类别"]', 'entity/法律相关/文书类别/法律文书类', 2, 0, '["09f98df9-1d2e-4e78-942e-827aa98c8340", "48257422-e389-4722-b0c7-f468b15d3b70", "f10d24ba-f395-4ea2-a362-82b161c78439", "545e625f-0915-4665-b5a1-d07622997253"]', '["6a519d6c-2d30-4827-9952-69ba0f039318", "da7ec3f0-3071-4cad-a761-ff740cd73287", "ca78f84e-1670-427c-99ef-936e764f2613", "4246bd2c-ded0-4e89-99c2-3a9b09f4f600", "9b6fc388-ac48-47df-a22d-e5acb19956de", "a291d9e0-96e2-40d6-9e2c-5055d21168d8", "8f530b67-c6f3-4ed6-acdc-bbd75a793b25", "a5f16c8d-e7b2-436b-a170-1ec267cfe818", "17fb92b5-7887-404e-ac6e-78a3f7194888", "15cd894e-0a80-47f2-8fcb-083b4c8d2e49", "bd312471-4277-4bc3-a706-219ae10ea96d", "2f5f8f97-9d75-4da1-ae16-71aad9a4d50b", "3982707d-7d60-4421-b11a-6f1e870bc56b", "56514901-34bb-4bf8-ab79-deb7a2ff52da", "724cbcad-70f4-4672-aaf9-830da3b99529", "ae127986-091e-455c-bcc8-609cc23433a6", "15c24a7b-d9b7-4654-af0d-239b490925b1", "f5982e15-34d1-4be6-b939-372121633041", "7adff4c4-e2b1-4729-89fb-7968eacaf74b", "fabb7dba-a327-4cd5-82f3-d95042f81d55", "e4705123-e2e5-4f47-9f4b-d4a6bf4594bb"]', 'null', '["concept/unemployment-insurance", "concept/work-injury-identification"]', NULL, '["法律文件类"]', 2, '2026-09-17 02:53:19.271573+00', '2026-09-17 03:10:16.427047+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('abeb4d47-1fa8-4ad7-87e9-a14080d7ccdd', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/pricing-backtracking-analysis', '定价回溯分析', 'concept', 'published', '# 定价回溯分析

**定价回溯分析**: 对保险产品定价假设的实际经营结果进行回溯验证的分析工作

## 预定利率回溯
### （一）定价预定利率
2025年，小康人寿在售长期险产品共25款。普通型保险中，定价利率2.5%产品8款，2.0%产品4款；分红型保险中，定价利率2.0%产品2款，1.75%产品5款，1.5%产品3款；万能型保险中，最低保证利率1.5%产品1款，1.0%产品1款，0.5%产品1款。

### （二）实际投资收益率
小康人寿近5年各账户实际经营投资收益率具体参见相关附表。

### （三）预定利率回溯结论
所有产品定价利率或最低保证利率均符合精算规定和相关监管要求。2025年9月1日前，在售长期普通型保险的定价利率不高于2.5%，在售分红型保险的定价利率不高于监管要求上限。

## [[concept/expense-rate-backtracking|费用率回溯]]
### （一）新业务费用率回溯分析
从公司整体来看，2025年精算可用费用可以完全覆盖销售费用及与销售相关的管理费用，但尚不能完全覆盖实际费用。实际费用高于精算可用费用的主要原因是公司整体业务规模较小，未实现规模效应，无法摊薄职场费用、内勤人力费用、资产使用费用和IT费用等管理费用。随着业务发展，实际/可用费用率将下降。

从产品线来看，人寿保险、年金保险和健康保险（销售+与销售相关的管理费用）/可用费用率分别为104.33%、95.45%、148.19%，销售/可用费用率分别为90.07%、89.09%和88.71%，2025年无新承保意外险业务。健康险因为新单保费收入占公司比例为0.10%，保费规模较小，所以（销售+与销售相关的管理费用）/可用费用率较高。

从渠道来看，银行代理渠道、公司直销渠道、中介代理渠道和互联网代理渠道（销售+与销售相关的管理费用）/可用费用率分别为96.76%、125.03%、123.57%、426.49%，销售/可用费用率分别为89.66%、72.22%、88.58%和81.67%。2025年银保渠道实现可用费用率覆盖销售费用及与销售相关的管理费用，其他渠道由于保费收入较小，（销售+与销售相关的管理费用）/可用费用率较高。

### （二）存量业务费用率回溯分析
2025年存量业务实际/可用费用率为223.74%，其中（销售+与销售相关的管理费用）/可用费用率102.01%，销售/可用费用率为85.89%。

从公司整体来看，2025年存量业务精算可用费用可以完全覆盖销售费用，略低于销售费用及与销售相关的管理费用之和，暂不能覆盖实际费用。实际费用高于精算可用费用的主要原因：一方面公司整体业务规模较小，未实现规模效应，无法摊薄职场费用、内勤人力费用、资产使用费用和IT费用等管理费用；另一方面存量业务中包含了较多已停售的“[[concept/combined-reporting-and-implementation|报行合一]]”前产品的续期业务，这部分续期业务存在续年预定附加费用率较低甚至为0，续年可用总费用无法覆盖管理费用。随着业务发展和“报行合一”的持续贯彻执行，实际/可用费用率将下降。

从产品线来看，人寿保险、年金保险和健康保险（销售+与销售相关的管理费用）/可用费用率分别为109.07%、94.54%、143.65%，销售/可用费用率分别为82.83%、87.90%和108.48%，2025年无新承保意外险业务。健康险销售/可用费用率较高，主要是由于中介代理渠道某产品导致，该产品为2023年备案产品，附加费用较低导致销售/可用费用率为138%，该产品已于2024年8月30日停售，2025年续期规模保费收入占公司规模保费收入比例仅0.38%。其他健康险续期可用费用高于销售费用。

从渠道来看，银行代理渠道、公司直销渠道、中介代理渠道和互联网代理渠道（销售+与销售相关的管理费用）/可用费用率分别为98.23%、125.03%、125.30%、426.49%，销售/可用费用率分别为86.90%、72.22%、79.01%和81.67%。

小康人寿将贯彻执行“报行合一”政策，为有效控制并降低实际/可用费用率，制定了下一步工作计划：一是扩大业务规模，优化业务结构。聚焦核心产品与优势渠道，加大市场拓展力度，提升业务保费规模，优化业务结构，逐步摊薄职场、内勤人力、资产使用及IT等管理费用。二是强化费用管控，优化费用结构。优化销售费用配置，进一步梳理销售费用结构，提升销售费用投产效能；严格把控管理费用支出，建立精细化费用管理体系，对职场费用、内勤人力费用、资产使用费用、IT费用等管理费用进行分类管控，压缩非必要支出，提高费用使用效率。同时，持续关注渠道和产品线的费用支出情况，提高公司费用管理水平，适时对费用假设进行适当调整，以真实反映公司实际经营情况。

## [[concept/surrender-rate-backtracking|退保率回溯]]
2025年，小康人寿整体预期退保金额1.79亿元，实际退保金额0.88亿元，实际/预期退保率49.29%，不存在较大的退保风险。

产品利润测试时，退保率假设参考《保险公司偿付能力监管规则》、行业经验数据和公司经验数据，按照保障储蓄属性、保险期间、交费期限等因素综合设置，长期来看，利润测试退保率假设符合寿险行业历史经验。

小康人寿2021年重新开业，前4年的实际退保率数据显示，进入第4年度保单样本量少，暂仅分析前3个年度保单退保情况。中介代理渠道保险期间10年以上储蓄型产品期缴且交费期内前2个年度实际退保率高于利润测试退保率假设，除此之外，实际退保率与利润测试退保率假设基本一致。中介代理渠道保险期间10年以上储蓄型产品期缴且交费期内前2个年度实际退保率较高，主要由2021-2023年承保业务导致，已于2024年采取相关举措，提高保单品质拉升继续率，2024年承保业务第1年度退保率约7%，接近利润测试退保率假设。

从产品线来看，人寿保险、年金保险和健康保险实际/预期退保率分别为51.76%、9.76%和33.90%。从渠道来看，银行代理渠道和中介代理渠道实际/预期退保率分别为47.26%和63.88%。

小康人寿将继续加强销售管理，避免销售误导，并继续加强售后服务工作，持续提高客户满意度。同时持续关注退保水平，适时对利润测试假设中的退保率假设进行适当调整，以真实反映公司实际经营情况。

## [[concept/investment-return-rate-backtracking|投资收益率回溯]]
回溯期末法定准备金余额排名前五的备案长期险产品中，5款产品责任准备金占公司准备金余额比例81.82%。除[[entity/xiaokangwenyingweilai-liangquanbaoxian|小康稳赢未来两全保险]]，其余4款产品相应账户近5年平均投资收益率高于利润测试投资收益率假设。小康稳赢未来两全保险相应的传统及资本金账户近5年平均投资收益率略低于产品利润测试投资收益率假设。

上述5款产品均为2021年下半年开发备案，小康人寿2021年重新开业，2016年至2020年5年平均投资收益率无参考意义，5款产品备案时采用的利润测试投资收益率主要参考2016年至2020年行业平均投资收益率5.22%和同业备案假设。5款产品均已于2023年7月30日停售。小康稳赢未来两全保险产品准备金余额占比较低，且保险期间为5年，产品利差损风险在可控范围内。

最新备案长期险产品定价利润测试投资收益率假设为3.90%，该假设低于2021年至2025年5年平均投资收益率6.07%。

小康人寿将持续加强资产负债匹配管理，合理配置投资资产，提升实际投资收益率水平；同时持续关注实际投资收益率水平及行业相关情况，适时对利润测试假设中的投资收益率假设进行适当调整，以真实反映公司实际经营情况。', '本文介绍定价回溯分析的定义，并结合小康人寿2025年度案例展示其具体分析维度和内容。', '', 'e9f282dd-2abf-4b5f-82ea-ab1c326fd97c', '["产品经营", "产品分析"]', 'concept/产品经营/产品分析/定价回溯分析', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["a0fa1acf-8761-450d-9722-9ff9a03bac34", "31c19c92-34d5-4641-90cd-8851c98ad96f", "47671b99-d207-4228-a41b-11ad6430facd", "6e44e4b2-1465-419d-84aa-bf07f476c601", "843dd970-6813-4a7c-af26-c57a79f9602d", "a394b991-0945-498d-b3b0-6dae1d31fac9", "24478a9a-6278-413b-9def-5f0e31ce9527", "518b54a7-58dc-4237-a3d3-f4b86af4a202", "47e23fad-1c45-429b-8872-61690fd21113", "2c64eee3-e3d9-4de3-b04a-54313604e59e", "87e7f8e1-9bf5-40a8-b506-cea78edc90c2", "0c49ff01-8ed8-4cca-8c53-b6a45ca552c2", "55156752-1b0a-44ac-9d5a-100d06af16e6", "8f8cb659-059b-42a2-9383-74da85a2f277", "89542175-e57a-4973-bdba-cae5307bedd8", "64617d60-943b-4f80-beb9-100f1244be21", "faf40a06-5dda-4d2e-a1b7-2f399af0bb28", "91638b2d-29c7-49f6-8fc2-1f3f2230a757", "b8511c5d-7524-42f5-b143-2bf228008271", "fa548abb-85ed-40c7-bb83-5467a81f8b86", "d1af5f28-5101-4fbf-b41b-b0ef76e03a4e", "fe25d198-2f13-41c0-b157-b208c8efa035", "75bad3dd-bdd3-4f23-b0de-a366a668b794", "17c0f7c1-bf17-4cb2-992c-315407766e3f"]', '["concept/insurance-product-backtracking", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', '["concept/expense-rate-backtracking", "concept/combined-reporting-and-implementation", "concept/surrender-rate-backtracking", "concept/investment-return-rate-backtracking", "entity/xiaokangwenyingweilai-liangquanbaoxian"]', NULL, '["产品定价回溯"]', 1, '2026-09-16 08:06:25.691036+00', '2026-09-16 08:07:16.527035+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('48043314-2335-459c-9d23-b747b3d48464', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/surrender-rate-backtracking', '退保率回溯', 'concept', 'published', '# 退保率回溯
退保率回溯是对比实际退保率与定价假设预期退保率的回溯分析。

## 退保率假设设置
公司在产品利润测试时，退保率假设参考《保险公司偿付能力监管规则》、行业经验数据和公司经验数据，按照保障储蓄属性、保险期间、交费期限等因素综合设置。长期来看，利润测试退保率假设符合寿险行业历史经验，具体设置如下：

| 保障储蓄属性 | 交费期 | 第1年度 | 第2年度 | 第3及之后年度 |
| ---- | ---- | ---- | ---- | ---- |
| 保障型产品 | 趸交或交费期后 | 5.00% | 5.00% | 5.00% |
| 保障型产品 | 期缴且交费期内 | 15.00% | 7.50% | 5.00% |
| 保险期间10年及以下储蓄型产品 | 趸交或期交 | 2.00% | 2.00% | 2.00% |
| 保险期间10年以上储蓄型产品 | 趸交或交费期后 | 2.00% | 2.00% | 2.00% |
| 保险期间10年以上储蓄型产品 | 期缴且交费期内 | 5.00% | 5.00% | 5.00% |

## 历史实际退保率
公司2021年重新开业，前4年的实际退保率如下：

| 保障储蓄属性 | 交费期 | 第1年度 | 第2年度 | 第3年度 | 第4年度 |
| ---- | ---- | ---- | ---- | ---- | ---- |
| 保障型产品 | 趸交或交费期后 | 0.00% | 0.00% | 0.00% | - |
| 保障型产品 | 期缴且交费期内 | 12.01% | 5.11% | 4.03% | 0.98% |
| 保险期间10年及以下储蓄型产品 | 趸交或期交 | 0.24% | 0.50% | 0.98% | 0.89% |
| 保险期间10年以上储蓄型产品（银行代理渠道） | 趸交或交费期后 | 0.35% | 0.96% | 0.51% | 6.41% |
| 保险期间10年以上储蓄型产品（银行代理渠道） | 期缴且交费期内 | 0.39% | 0.20% | 0.00% | 0.00% |
| 保险期间10年以上储蓄型产品（中介代理渠道） | 趸交或交费期后 | 2.34% | 2.15% | 2.22% | 7.38% |
| 保险期间10年以上储蓄型产品（中介代理渠道） | 期缴且交费期内 | 25.16% | 10.61% | 5.62% | 1.42% |

公司进入第4年度保单样本量少，暂仅分析前3个年度保单退保情况。中介代理渠道保险期间10年以上储蓄型产品期缴且交费期内前2个年度实际退保率高于利润测试退保率假设，除此之外，实际退保率与利润测试退保率假设基本一致。中介代理渠道保险期间10年以上储蓄型产品期缴且交费期内前2个年度实际退保率较高，主要由2021-2023年承保业务导致，公司已于2024年采取相关举措，提高保单品质拉升继续率，2024年承保业务第1年度退保率约7%，接近利润测试退保率假设。

## 2025年退保率回溯结果
2025年，公司整体预期退保金额1.79亿元，实际退保金额0.88亿元，实际/预期退保率49.29%，不存在较大的退保风险。

### 按产品线划分
单位：万元，%
| 产品线 | 实际退保金额 | 预期退保金额 | 实际/预期退保率 |
| ---- | ---- | ---- | ---- |
| 人寿保险 | 8703.74 | 16816.37 | 51.76% |
| 年金保险 | 101.71 | 1041.76 | 9.76% |
| 意外伤害保险 | - | - | —— |
| 健康保险 | 8.50 | 25.06 | 33.90% |
| 公司整体 | 8813.94 | 17883.20 | 49.29% |

从产品线来看，人寿保险、年金保险和健康保险实际/预期退保率分别为 51.76%、9.76% 和33.90%。

### 按渠道划分
单位：万元，%
| 渠道 | 实际退保金额 | 预期退保金额 | 实际/预期退保率 |
| ---- | ---- | ---- | ---- |
| 银行代理渠道 | 7416.77 | 15693.97 | 47.26% |
| 公司直销渠道 | - | 1.16 | 0.00% |
| 中介代理渠道 | 1397.79 | 2187.98 | 63.88% |
| 互联网代理渠道 | - | 0.09 | 0.00% |
| 公司整体 | 8814.56 | 17883.20 | 49.29% |

从渠道来看，银行代理渠道和中介代理渠道实际/预期退保率分别为 47.26% 和 63.88%。

## 后续计划
公司将继续加强销售管理，避免销售误导，并继续加强售后服务工作，持续提高客户满意度。公司也将持续关注公司退保水平，适时对利润测试假设中的退保率假设进行适当调整，以真实反映公司实际经营情况。', '本页面介绍退保率回溯的概念，以及小康人寿2025年退保率回溯的具体分析结果和相关计划。', '', 'e9f282dd-2abf-4b5f-82ea-ab1c326fd97c', '["产品经营", "产品分析"]', 'concept/产品经营/产品分析/退保率回溯', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["8f8cb659-059b-42a2-9383-74da85a2f277", "89542175-e57a-4973-bdba-cae5307bedd8", "64617d60-943b-4f80-beb9-100f1244be21", "faf40a06-5dda-4d2e-a1b7-2f399af0bb28", "91638b2d-29c7-49f6-8fc2-1f3f2230a757", "b8511c5d-7524-42f5-b143-2bf228008271", "fa548abb-85ed-40c7-bb83-5467a81f8b86"]', '["concept/pricing-backtracking-analysis", "concept/insurance-product-backtracking", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', 'null', NULL, '[]', 1, '2026-09-16 08:06:26.634036+00', '2026-09-16 08:07:16.539345+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('a479e1cb-2803-4c4a-ab8b-0332ac259d49', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'entity/social-insurance-funds', '社会保险基金类', 'entity', 'published', '# 社会[[entity/insurance-funds|保险基金类]]

社会保险基金类是指通过多种渠道筹集，用于[[concept/social-insurance-benefits|社会保险待遇]]支付等用途的专项资金类别，按险种分类管理。

## 涵盖范围
社会保险基金包括以下险种基金：
1. 基本养老保险基金
2. 基本医疗保险基金
3. 工伤保险基金
4. [[concept/unemployment-insurance|失业保险]]基金
5. 生育保险基金

除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算，执行国家统一的会计制度。

## 主要特征
1. **专款专用**：社会保险基金专款专用，任何组织和个人不得侵占或者挪用。
2. **财政专户管理**：社会保险基金存入财政专户，具体管理办法由国务院规定。
3. **预算管理**：社会保险基金通过预算实现收支平衡，按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。
4. **统筹层次**：基本养老保险基金逐步实行全国统筹，其他社会保险基金逐步实行省级统筹，具体时间、步骤由国务院规定。
5. **保值增值**：社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。
6. **信息公开**：社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。

## 基金筹集
社会保险基金通过多渠道筹集，县级以上人民政府对社会保险事业给予必要的经费支持，国家通过税收优惠政策支持社会保险事业。县级以上人民政府在社会保险基金出现支付不足时，给予补贴。

## 禁止性规定
社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。

## 监督管理
国务院和省、自治区、直辖市人民政府建立健全社会保险基金监督管理制度，保障社会保险基金安全、有效运行。县级以上人民政府采取措施，鼓励和支持社会各方面参与社会保险基金的监督。

违反法律规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。', '社会保险基金类是按险种分类管理、专款专用的专项资金类别，涵盖五大险种基金，实行财政专户与预算管理。', '', 'b5088f1c-4199-4c75-abbb-9a88cc4c0aff', '["社会保险", "社会保险基金"]', 'entity/社会保险/社会保险基金/社会保险基金类', 2, 0, '["48257422-e389-4722-b0c7-f468b15d3b70", "a80a58b2-6424-4d94-a41a-a97be2e9999e"]', '["248caf30-67a1-4760-a27a-e24ac52855f8", "10993fad-f9e1-4e31-a155-0cfb4edecc8b", "a291d9e0-96e2-40d6-9e2c-5055d21168d8", "77db5cc9-bd0c-432f-aa1d-ff83ebbf1661", "1ea7c4ec-0268-4f4a-ad86-ced19199d79b", "8fece6d2-202f-4666-a50e-369e99878a88", "b3c6dcdf-a037-4137-b2e0-cafb7b61aab7", "9e6e682d-ad63-438a-8403-534aedd8b381", "8e6cf773-06fb-48a1-b962-b99ee8edaa04", "05a57191-1de2-4563-a8a5-47fdcfe6c863", "7f906034-f8ab-40a1-8b2e-f81047fe650b", "0df54303-6419-4a10-b6f7-6a4d6dab484b", "3bfaf175-d4f1-4e01-bc0c-a1ac8e7c08ce", "b696cb43-c2bd-4507-9d7d-de0d88e71a67", "0d21acf2-7447-4413-8be0-5ad7e01b8b00", "aa6bc7c8-790e-4206-afe6-34dfcf02a15d", "8366b0f7-b76d-49e8-a90e-e042d00febcd", "984924ee-3136-45f7-b455-e8ce6fc4b408", "fd01b5d3-c8f4-4c9a-9ea6-98066ed5fcbd", "fb14e177-7756-4836-a109-ae9f04d549e1", "ef34775e-8716-4323-8d2b-abff24bea709", "f836d295-07b6-44f5-8c59-9e71362849b9"]', '["summary/a80a58b2-6424-4d94-a41a-a97be2e9999e"]', '["entity/insurance-funds", "concept/social-insurance-benefits", "concept/unemployment-insurance"]', NULL, '["社保基金类"]', 1, '2026-09-17 03:08:55.947561+00', '2026-09-17 03:10:16.528297+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('f0332894-c7ac-4e60-baff-ebf2e8beefcc', 10000, 'fea2b625-3403-47de-a234-1da12207f16e', 'concept/insurance-guarantee-fund', '保险保障基金', 'concept', 'published', '# 保险保障基金

保险保障基金是由保险公司缴纳、集中管理统筹使用，用于保险业风险救助的专项基金。

## 缴纳要求
保险公司应当依法缴纳保险保障基金。

## 管理与使用
保险保障基金应当集中管理，并在下列情形下统筹使用：
1. 在保险公司被撤销或者被宣告破产时，向投保人、被保险人或者受益人提供救济；
2. 在保险公司被撤销或者被宣告破产时，向依法接受其人寿保险合同的保险公司提供救济；
3. 国务院规定的其他情形。

保险保障基金筹集、管理和使用的具体办法，由国务院制定。

## 法律责任
保险公司未按照规定缴纳保险保障基金的，由保险监督管理机构责令改正，处五万元以上三十万元以下的罚款；情节严重的，可以限制其业务范围、责令停止接受新业务或者吊销业务许可证。', '保险保障基金是由保险公司缴纳、集中管理统筹使用，用于保险业风险救助的专项基金。', '', 'e4c73d30-779c-4bac-a89f-ec486eb68f02', '["保险监管", "监管制度"]', 'concept/保险监管/监管制度/保险保障基金', 2, 0, '["f10d24ba-f395-4ea2-a362-82b161c78439"]', '["5ca8e472-f236-4010-a164-ff73e507445a", "2b02f802-00ab-44b0-bbbe-b448c71e4f92"]', '["concept/solvency"]', 'null', NULL, '[]', 1, '2026-09-17 03:08:57.606893+00', '2026-09-17 03:10:16.62048+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('42741ddc-c459-4249-9611-c50ee8072188', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/expense-rate-backtracking', '费用率回溯', 'concept', 'published', '# 费用率回溯
费用率回溯是对比产品实际费用与定价假设可用费用的回溯分析。“[[concept/combined-reporting-and-implementation|报行合一]]”后，产品附加费用率即利润测试时的可用总费用水平。

## 在售产品费用率回溯分析
2025年在售产品实际/可用费用率为146.22%，其中（销售+与销售相关的管理费用）/可用费用率为99.81%，销售/可用费用率为89.53%。和去年相比，实际/可用费用率下降9.16%，销售/可用费用率下降2.54%。2025年度公司可用费用率除覆盖销售费用外，同时覆盖了销售费用及与销售相关的管理费用。

各产品线数据（单位：万元，%）：
|产品线|实际费用|其中：销售费用|其中：与销售相关的管理费用|精算可用费用|实际/可用费用率|(销售+与销售相关的管理费用)/可用费用率|销售/可用费用率|
| ---- | ---- | ---- | ---- | ---- | ---- | ---- | ---- |
|人寿保险|5113.83|2785.84|440.99|3092.91|165.34%|104.33%|90.07%|
|年金保险|4878.78|3390.80|241.95|3805.88|128.19%|95.45%|89.09%|
|意外伤害保险|-|-|-|-|——|——|——|
|健康保险|173.63|47.62|31.93|53.68|323.46%|148.19%|88.71%|
|公司整体|10166.25|6224.26|714.87|6952.47|146.22%|99.81%|89.53%|

各渠道数据（单位：万元，%）：
|渠道|实际费用|其中：销售费用|其中：与销售相关的管理费用|精算可用费用|实际/可用费用率|(销售+与销售相关的管理费用)/可用费用率|销售/可用费用率|
| ---- | ---- | ---- | ---- | ---- | ---- | ---- | ---- |
|银行代理渠道|7758.10|5602.06|443.58|6248.32|124.16%|96.76%|89.66%|
|公司直销渠道|43.32|4.51|3.30|6.25|693.06%|125.03%|72.22%|
|中介代理渠道|2320.61|611.40|241.49|690.22|336.21%|123.57%|88.58%|
|互联网代理渠道|44.22|6.27|26.49|7.68|575.57%|426.49%|81.67%|
|公司整体|10166.25|6224.26|714.87|6952.47|146.22%|99.81%|89.53%|

从公司整体来看，2025年精算可用费用可以完全覆盖销售费用及与销售相关的管理费用，但尚不能完全覆盖实际费用。实际费用高于精算可用费用的主要原因是公司整体业务规模较小，未实现规模效应，无法摊薄职场费用、内勤人力费用、资产使用费用和IT费用等管理费用。随着业务发展，实际/可用费用率将下降。

从产品线来看，人寿保险、年金保险和健康保险（销售+与销售相关的管理费用）/可用费用率分别为104.33%、95.45%、148.19%，销售/可用费用率分别为90.07%、89.09%和88.71%，2025年无新承保意外险业务。健康险因为新单保费收入占公司比例为0.10%，保费规模较小，所以（销售+与销售相关的管理费用）/可用费用率较高。

从渠道来看，银行代理渠道、公司直销渠道、中介代理渠道和互联网代理渠道（销售+与销售相关的管理费用）/可用费用率分别为96.76%、125.03%、123.57%、426.49%，销售/可用费用率分别为89.66%、72.22%、88.58%和81.67%。2025年银保渠道实现可用费用率覆盖销售费用及与销售相关的管理费用，其他渠道由于保费收入较小，（销售+与销售相关的管理费用）/可用费用率较高。

## 存量业务费用率回溯分析
2025年存量业务实际/可用费用率为223.74%，其中（销售+与销售相关的管理费用）/可用费用率102.01%，销售/可用费用率为85.89%。

各产品线数据（单位：万元，%）：
|产品线|实际费用|其中：销售费用|其中：与销售相关的管理费用|精算可用费用|实际/可用费用率|(销售+与销售相关的管理费用)/可用费用率|销售/可用费用率|
| ---- | ---- | ---- | ---- | ---- | ---- | ---- | ---- |
|人寿保险|11093.42|2820.48|893.50|3405.25|325.77%|109.07%|82.83%|
|年金保险|5110.20|3400.53|256.68|3868.63|132.09%|94.54%|87.90%|
|意外伤害保险|-|-|-|-|——|——|——|
|健康保险|331.72|126.48|41.01|116.60|284.51%|143.65%|108.48%|
|公司整体|16535.34|6347.49|1191.19|7390.47|223.74%|102.01%|85.89%|

各渠道数据（单位：万元，%）：
|渠道|实际费用|其中：销售费用|其中：与销售相关的管理费用|精算可用费用|实际/可用费用率|(销售+与销售相关的管理费用)/可用费用率|销售/可用费用率|
| ---- | ---- | ---- | ---- | ---- | ---- | ---- | ---- |
|银行代理渠道|11757.30|5600.58|730.16|6444.87|182.43%|98.23%|86.90%|
|公司直销渠道|43.32|4.51|3.30|6.25|693.06%|125.03%|72.22%|
|中介代理渠道|4690.50|736.12|431.24|931.67|503.45%|125.30%|79.01%|
|互联网代理渠道|44.22|6.27|26.49|7.68|575.57%|426.49%|81.67%|
|公司整体|16535.34|6347.49|1191.19|7390.47|223.74%|102.01%|85.89%|

从公司整体来看，2025年存量业务精算可用费用可以完全覆盖销售费用，略低于销售费用及与销售相关的管理费用之和，暂不能覆盖实际费用。实际费用高于精算可用费用的主要原因：一方面公司整体业务规模较小，未实现规模效应，无法摊薄职场费用、内勤人力费用、资产使用费用和IT费用等管理费用；另一方面存量业务中包含了较多已停售的“报行合一”前产品的续期业务，这部分续期业务存在续年预定附加费用率较低甚至为0，续年可用总费用无法覆盖管理费用。随着业务发展和“报行合一”的持续贯彻执行，实际/可用费用率将下降。

从产品线来看，人寿保险、年金保险和健康保险（销售+与销售相关的管理费用）/可用费用率分别为109.07%、94.54%、143.65%，销售/可用费用率分别为82.83%、87.90%和108.48%，2025年无新承保意外险业务。健康险销售/可用费用率较高，主要是由于中介代理渠道《[[entity/xiaokang-kangweizhi-wuyouban-zhongdajibing-baoxian|小康康卫士（无忧版）重大疾病保险]]》导致，该产品为2023年备案产品，附加费用较低导致销售/可用费用率为138%，该产品已于2024年8月30日停售，2025年续期规模保费收入占公司规模保费收入比例仅0.38%。其他健康险续期可用费用高于销售费用。

从渠道来看，银行代理渠道、公司直销渠道、中介代理渠道和互联网代理渠道（销售+与销售相关的管理费用）/可用费用率分别为98.23%、125.03%、125.30%、426.49%，销售/可用费用率分别为86.90%、72.22%、79.01%和81.67%。

## 下一步工作计划
为有效控制并降低实际/可用费用率，将贯彻执行“报行合一”政策，实施两项计划：
1. 扩大业务规模，优化业务结构。聚焦核心产品与优势渠道，加大市场拓展力度，提升业务保费规模，优化业务结构，逐步摊薄职场、内勤人力、资产使用及IT等管理费用。
2. 强化费用管控，优化费用结构。优化销售费用配置，进一步梳理销售费用结构，提升销售费用投产效能；严格把控管理费用支出，建立精细化费用管理体系，对职场费用、内勤人力费用、资产使用费用、IT费用等管理费用进行分类管控，压缩非必要支出，提高费用使用效率。

同时，将持续关注渠道和产品线的费用支出情况，提高公司费用管理水平，适时对费用假设进行适当调整，以真实反映公司实际经营情况。', '本页面介绍保险产品费用率回溯的概念，基于小康人寿2025年回溯数据分析相关结果和改进计划。', '', 'e9f282dd-2abf-4b5f-82ea-ab1c326fd97c', '["产品经营", "产品分析"]', 'concept/产品经营/产品分析/费用率回溯', 2, 0, '["dc307d27-e28a-4b32-a250-03358683a9b7"]', '["db9461df-231c-4f81-b826-0c331a432e23", "bbe82afb-bb16-4fe2-b4af-e21212b3358c", "6208db5f-1a04-4b8f-97e4-5292df95720d", "82c27d05-8f04-42ec-a936-ae475c843b9b", "47671b99-d207-4228-a41b-11ad6430facd", "6e44e4b2-1465-419d-84aa-bf07f476c601", "843dd970-6813-4a7c-af26-c57a79f9602d", "a394b991-0945-498d-b3b0-6dae1d31fac9", "24478a9a-6278-413b-9def-5f0e31ce9527", "518b54a7-58dc-4237-a3d3-f4b86af4a202", "47e23fad-1c45-429b-8872-61690fd21113", "2c64eee3-e3d9-4de3-b04a-54313604e59e", "87e7f8e1-9bf5-40a8-b506-cea78edc90c2", "0c49ff01-8ed8-4cca-8c53-b6a45ca552c2", "55156752-1b0a-44ac-9d5a-100d06af16e6", "8f8cb659-059b-42a2-9383-74da85a2f277"]', '["concept/pricing-backtracking-analysis", "concept/insurance-product-backtracking", "entity/xiaokang-shouxian-baoxian-youxian-zere-gs"]', '["concept/combined-reporting-and-implementation", "entity/xiaokang-kangweizhi-wuyouban-zhongdajibing-baoxian"]', NULL, '[]', 1, '2026-09-16 08:06:39.905361+00', '2026-09-16 08:07:16.537655+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('0893f69f-8dd3-4994-8a96-f051c84055b8', 10000, 'eae6cd64-1a52-4012-b52d-a94d9f7de4fa', 'summary/c7248c16-1454-4c10-b366-78873d08cd9e', '工伤保险条例_32946290.pdf - Summary', 'summary', 'published', '## 概述
《工伤保险条例》于2003年4月27日以中华人民共和国国务院令第375号公布，2010年12月20日根据《国务院关于修改〈工伤保险条例〉的决定》修订，属于[[entity/laws-and-regulations|法律法规类]]范畴。该条例旨在保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险。

## 适用范围与管理体制
### 适用主体
中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户（以下称用人单位）应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工缴纳工伤保险费。上述组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。相关主体属于[[entity/legal-subjects|法律主体类]]范畴。

### 管理部门
国务院社会保险行政部门负责全国的工伤保险工作，县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。社会保险行政部门按照国务院有关规定设立的社会保险经办机构具体承办工伤保险事务，属于[[entity/regulatory-institutions|监管机构类]]范畴。

## 工伤保险基金
[[entity/insurance-funds|保险基金类]]由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。
- **征缴规则**：工伤保险费根据以支定收、收支平衡的原则确定[[concept/work-injury-insurance-rate|工伤保险费率]]。国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。职工个人不缴纳工伤保险费。
- **统筹管理**：工伤保险基金逐步实行省级统筹，跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险，属于[[concept/work-injury-insurance-coordination|工伤保险统筹]]范畴。
- **基金用途**：用于工伤保险待遇，劳动能力鉴定，[[concept/work-injury-prevention|工伤预防]]的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。
- **储备金制度**：工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。

## 工伤认定
[[concept/work-injury-identification|工伤认定]]是工伤保险制度的核心环节，相关程序属于[[entity/legal-acts-and-procedures|法律行为与程序类]]范畴。
### 认定情形
- **应当认定为工伤**：在工作时间和工作场所内，因工作原因受到事故伤害的；工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的；在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；患职业病的；因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的；法律、行政法规规定应当认定为工伤的其他情形。
- **视同工伤**：在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的；在抢险救灾等维护国家利益、公共利益活动中受到伤害的；职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。
- **不得认定为工伤或者视同工伤**：故意犯罪的；醉酒或者吸毒的；自残或者自杀的。

### 认定程序
- **申请时限**：职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。
- **申请材料**：工伤认定申请表；与用人单位存在劳动关系（包括事实劳动关系）的证明材料；医疗诊断证明或者职业病诊断证明书（或者职业病诊断鉴定书）。
- **认定时限**：社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。

## 劳动能力鉴定
职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行[[concept/labor-ability-appraisal|劳动能力鉴定]]。
- **鉴定等级**：劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。
- **鉴定程序**：劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。
- **再次鉴定与复查鉴定**：申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。

## 工伤保险待遇
[[entity/insurance-benefits|保险待遇类]]是工伤保险制度的核心内容，保障工伤职工的合法权益。
- **工伤医疗待遇**：职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。
- **停工留薪期**：职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在[[concept/work-injury-leave-period|停工留薪期]]内，原工资福利待遇不变，由所在单位按月支付。停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。
- **伤残待遇**：
  - 一级至四级伤残：保留劳动关系，退出工作岗位，从工伤保险基金按伤残等级支付一次性伤残补助金，按月支付伤残津贴。工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。
  - 五级、六级伤残：从工伤保险基金按伤残等级支付一次性伤残补助金；保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴。经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。
  - 七级至十级伤残：从工伤保险基金按伤残等级支付一次性伤残补助金；劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。
- **工亡待遇**：职工因工死亡，其近亲属按照规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金。丧葬补助金为6个月的统筹地区上年度职工月平均工资；一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。

## 监督管理与法律责任
### 监督管理
经办机构具体承办工伤保险事务，履行征收工伤保险费、办理工伤保险登记、核定工伤保险待遇等职责。社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。

### 法律责任
[[entity/legal-liabilities|法律责任类]]涵盖对各类违法行为的惩处：
- 挪用工伤保险基金的，构成犯罪的依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。
- 社会保险行政部门工作人员、经办机构有违法行为的，依法给予处分或者纪律处分；情节严重构成犯罪的，依法追究刑事责任；造成当事人经济损失的，依法承担赔偿责任。
- 用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重构成犯罪的，依法追究刑事责任。
- 用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。

## 要点总结
- 《工伤保险条例》是规范工伤保险制度的行政法规，旨在保障工伤职工权益，分散用人单位工伤风险。
- 工伤保险基金由用人单位缴费等构成，实行行业差别费率和浮动费率，逐步实现省级统筹。
- 工伤认定包括应当认定、视同工伤和不得认定三种情形，需按法定程序申请和作出决定。
- 劳动能力鉴定分为劳动功能障碍十级和生活自理障碍三级，是确定伤残待遇的依据。
- 工伤保险待遇涵盖医疗待遇、停工留薪期待遇、伤残待遇和工亡待遇等多个方面。
- 条例明确了监督管理体制和各类违法行为的法律责任，保障制度的规范运行。', '《工伤保险条例》规范工伤保险制度，涵盖基金、认定、鉴定、待遇、监管及法律责任等内容。', '', '', '[]', 'summary/工伤保险条例_32946290.pdf - Summary', 0, 0, '["c7248c16-1454-4c10-b366-78873d08cd9e"]', '[]', 'null', '["entity/laws-and-regulations", "entity/legal-subjects", "entity/regulatory-institutions", "entity/insurance-funds", "concept/work-injury-insurance-rate", "concept/work-injury-insurance-coordination", "concept/work-injury-prevention", "concept/work-injury-identification", "entity/legal-acts-and-procedures", "concept/labor-ability-appraisal", "entity/insurance-benefits", "concept/work-injury-leave-period", "entity/legal-liabilities"]', NULL, '[]', 1, '2026-09-17 05:49:40.055213+00', '2026-09-17 05:50:06.615265+00', NULL, 'pipeline', '');
INSERT INTO "public"."wiki_pages" VALUES ('d57d4d92-52b9-4470-be57-996d547f1653', 10000, '5abc2a30-987a-4561-9c8b-6df0476c12c6', 'concept/insurance-product-operation', '保险产品经营', 'concept', 'published', '# 保险产品经营

保险产品经营指保险产品整体保费收入、结构、渠道等经营数据情况。

## [[entity/xiaokang-shouxian-baoxian-youxian-zere-gs|小康人寿保险有限责任公司]]2025年度产品经营情况

### 总体经营情况
小康人寿以客户利益优先为开发导向，平衡费率与费用实现可持续发展。2025年总保费11.07亿元，同比增长35.63%；新单保费6.53亿元，同比增长42.01%。

### 保费结构

#### 产品类型维度
|产品类型|新单保费（亿元）|同比增速|总保费（亿元）|总保费占比|总保费占比变动|
|---|---|---|---|---|---|
|人寿保险|4.45|28.26%|7.93|71.62%|-12.30%|
|年金保险|2.07|87.22%|3.03|27.35%|12.71%|
|健康保险|0.01|-69.62%|0.11|1.03%|-0.41%|
|意外伤害保险|-|-100.00%|-|0.00%|0.00001%|
|公司整体|6.53|42.01%|11.07|100.00%|0.00%|

注：小康人寿2024年及2025年意外伤害保险均无新业务，其中2024年因团体意外险减保导致保费减少81.72元、总保费占比为-0.00001%，因此2025年新单保费较2024年同比增速为-100%、总保费占比较2024年提升0.00001%。

#### 销售渠道维度
|销售渠道|新单保费（亿元）|同比增速|总保费（亿元）|总保费占比|总保费占比变动|
